// Theme Context
type Theme = 'dark' | 'light';
const ThemeContext = createContext<{ theme: Theme; toggleTheme: () => void }>({
  theme: 'dark',
  toggleTheme: () => {},
});

export const useTheme = () => useContext(ThemeContext);

const CustomCursor: React.FC = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);
  const [trail, setTrail] = useState<{ x: number; y: number; id: number }[]>([]);
  const cursorRef = useRef({ x: 0, y: 0 });
  const { theme } = useTheme();

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      const { clientX, clientY } = e;
      cursorRef.current = { x: clientX, y: clientY };
      setPosition({ x: clientX, y: clientY });

      setTrail((prev) => [
        { x: clientX, y: clientY, id: Date.now() },
        ...prev.slice(0, 8),
      ]);
    };

    const handleMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'A' || target.tagName === 'BUTTON' || target.closest('a') || target.closest('button')) {
        setIsHovering(true);
      } else {
        setIsHovering(false);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseover', handleMouseOver);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseover', handleMouseOver);
    };
  }, []);

  return (
    <>
      <div 
        className={`fixed top-0 left-0 w-8 h-8 rounded-full border-2 z-[9999] pointer-events-none transition-transform duration-100 ease-out mix-blend-difference ${theme === 'dark' ? 'border-white' : 'border-black'}`}
        style={{ 
          transform: `translate(${position.x - 16}px, ${position.y - 16}px) scale(${isHovering ? 2 : 1})`,
        }}
      />
      <div 
        className={`fixed top-0 left-0 w-1.5 h-1.5 rounded-full z-[9999] pointer-events-none mix-blend-difference ${theme === 'dark' ? 'bg-white' : 'bg-black'}`}
        style={{ transform: `translate(${position.x - 3}px, ${position.y - 3}px)` }}
      />
      {trail.map((dot, index) => (
        <div 
          key={dot.id}
          className={`fixed top-0 left-0 rounded-full z-[9998] pointer-events-none transition-opacity duration-500 opacity-20 ${theme === 'dark' ? 'bg-pink-500' : 'bg-blue-500'}`}
          style={{ 
            width: `${10 - index}px`,
            height: `${10 - index}px`,
            transform: `translate(${dot.x - (10 - index) / 2}px, ${dot.y - (10 - index) / 2}px)`,
            opacity: (1 - index / trail.length) * 0.3
          }}
        />
      ))}
    </>
  );
};

const ScrollToTop = () => {
